INSERT INTO clubs (name, address, website, city, state, zip_code, country, club_type, description, visible, status)
SELECT c.name, c.address, c.website, c.city, c.state, c.zip_code, c.country, c.club_type, c.description, FALSE, 'active'
FROM candidates c
WHERE NOT EXISTS (
    SELECT 1
    FROM clubs existing
    WHERE regexp_replace(lower(existing.name), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(c.name), '[^a-z0-9]+', '', 'g')
       OR (
            c.state IS NOT NULL
        AND regexp_replace(lower(split_part(existing.address, ',', 1)), '[^a-z0-9]+', '', 'g') <> ''
        AND regexp_replace(lower(split_part(c.address, ',', 1)), '[^a-z0-9]+', '', 'g') <> ''
        AND regexp_replace(lower(split_part(existing.address, ',', 1)), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(split_part(c.address, ',', 1)), '[^a-z0-9]+', '', 'g')
        AND COALESCE(existing.state, '') = COALESCE(c.state, '')
       )
       OR (
            lower(COALESCE(existing.city, '')) = lower(COALESCE(c.city, ''))
        AND COALESCE(existing.state, '') = COALESCE(c.state, '')
        AND least(
              length(regexp_replace(lower(existing.name), '[^a-z0-9]+', '', 'g')),
              length(regexp_replace(lower(c.name), '[^a-z0-9]+', '', 'g'))
            ) >= 8
        AND (
              position(regexp_replace(lower(existing.name), '[^a-z0-9]+', '', 'g') in regexp_replace(lower(c.name), '[^a-z0-9]+', '', 'g')) > 0
           OR position(regexp_replace(lower(c.name), '[^a-z0-9]+', '', 'g') in regexp_replace(lower(existing.name), '[^a-z0-9]+', '', 'g')) > 0
        )
       )
);
